#!/usr/bin/env node
// Verifies local setup before `npm run dev` / `npm run build`:
//   1. ms.config.json exists (created by `npx ms app init`) with an appId and environmentId, and
//   2. the connector code generated by the `ms` CLI exists in generated/ and
//      exports the services the adapters in src/connectors/ wrap.
// Prints exact fix-up steps and exits 1 when something is missing.
// `npm test` and `npm run lint` never need this; they work on a fresh clone.
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Connector -> generated service the adapter in src/connectors/ imports, and the operations it calls. */
const CONNECTORS = [
  {
    apiId: "shared_visualstudioteamservices",
    name: "Azure DevOps",
    service: "AzureDevOpsService",
    operations: ["HttpRequest", "CreateWorkItem", "UpdateWorkItem", "AddWorkItemLinkAsync", "ListWorkItems", "ListBuildRequestersAsync"],
    adapter: "src/connectors/azureDevOps.ts",
  },
  {
    apiId: "shared_teams",
    name: "Teams",
    service: "MicrosoftTeamsService",
    operations: ["PostMessageToConversation"],
    adapter: "src/connectors/teams.ts",
  },
  {
    apiId: "shared_office365users",
    name: "Office 365 Users",
    service: "Office365UsersService",
    operations: ["MyProfile_V2", "UserPhotoMetadata", "UserPhoto"],
    adapter: "src/connectors/office365Users.ts",
  },
];

const problems = [];

// 1. ms.config.json placeholders
const configPath = join(root, "ms.config.json");
if (!existsSync(configPath)) {
  problems.push("ms.config.json is missing: the app hasn't been created yet (npx ms app init).");
} else {
  let config = null;
  try {
    config = JSON.parse(readFileSync(configPath, "utf8"));
  } catch {
    problems.push("ms.config.json is not valid JSON.");
  }
  for (const key of config ? ["appId", "environmentId"] : []) {
    const value = config[key];
    if (typeof value !== "string" || !value.trim() || value.includes("<")) {
      problems.push(`ms.config.json has no valid "${key}".`);
    }
  }
}

// 2. generated connector services
const indexPath = join(root, "generated", "index.ts");
const index = existsSync(indexPath) ? readFileSync(indexPath, "utf8") : null;
if (index === null) problems.push("generated/index.ts is missing (no connectors have been added yet).");
const missingConnectors = [];
for (const connector of CONNECTORS) {
  const servicePath = join(root, "generated", "services", `${connector.service}.ts`);
  const exported = index !== null && index.includes(`./services/${connector.service}`);
  if (!exported || !existsSync(servicePath)) {
    missingConnectors.push(connector);
    if (index !== null) problems.push(`generated/ does not export ${connector.service} (${connector.name}).`);
    continue;
  }
  const source = readFileSync(servicePath, "utf8");
  if (!new RegExp(`export class ${connector.service}\\b`).test(source)) {
    problems.push(`generated/services/${connector.service}.ts does not export class ${connector.service}.`);
  }
  const missingOps = connector.operations.filter((op) => !new RegExp(`static async ${op}\\(`).test(source));
  if (missingOps.length > 0) {
    problems.push(
      `${connector.service} is missing operations used by ${connector.adapter}: ${missingOps.join(", ")}. ` +
        `If the CLI reported actions "skipped due to your organization's connector policy", ask your admin to allow ` +
        `these actions, then run: npx ms app refresh data-source. Otherwise re-run that command or update the adapter.`,
    );
  }
}

if (problems.length === 0) {
  console.log("check-setup: ms.config.json and connector code look good.");
  process.exit(0);
}

const toAdd = missingConnectors.length > 0 ? missingConnectors : index === null ? CONNECTORS : [];
console.error(`
Task Manager isn't set up yet:
${problems.map((p) => `  - ${p}`).join("\n")}

Follow .github/skills/setup-taskmanager/SKILL.md (or README.md › Setup). In short:

  1. Sign in:            npx ms auth login
  2. Create the app:     npx ms app init --display-name "Task Manager" --environment-id <ENVIRONMENT_ID> --icon-path ./public/task-manager-icon.png
                         npx ms app set-setting --show-header false
  3. Add ALL connectors (each generates code into generated/):
${(toAdd.length > 0 ? toAdd : CONNECTORS)
  .map((c) => `       npx ms app add data-source --connector ${c.apiId} --as action    # ${c.name}`)
  .join("\n")}
  4. Configure:          copy .env.example to .env.local and set VITE_ADO_ORG / VITE_ADO_PROJECT
  5. Verify:             npm run check-setup
`);
process.exit(1);
